<script setup lang="ts">
import {computed,ref} from 'vue';import type {Console,Row} from '../console';import Icon from './Icon.vue';import OriginsList from './OriginsList.vue';
const props=defineProps<{c:Console}>();const result=ref<Row[]|null>(null);
function flatten(nodes:Row[],depth=0):Row[]{return nodes.flatMap(n=>[{...n.permission,granted:n.granted,depth},...flatten(n.children||[],depth+1)]);}
const menu=computed(()=>flatten(props.c.s.myMenu));
</script>
<template><div class="personal-summary"><div><span class="badge green"><i/>当前账号有效</span><h2>{{c.s.me?.displayName}}，这是你的访问空间。</h2><p class="muted">共 {{c.s.myPermissions.length}} 项有效权限。权限变化会在下一次请求中重新计算。</p></div><Icon name="key" :size="50"/></div><section class="panel"><div class="section-heading"><div><h2>权限与来源</h2><p class="muted">直接授权与继承授权分别标记；相同权限只列一次。</p></div><button :disabled="c.s.busy" @click="c.run(c.refresh)"><Icon name="refresh"/>刷新权限</button></div><OriginsList :items="c.s.origins" :roles="c.s.me?.administrator?c.s.roles:undefined"/></section><div class="two-columns"><section class="panel"><div class="section-heading"><h2>我的导航</h2><span class="count">{{menu.length}}</span></div><p class="muted">仅用于组织导航的祖先菜单，不会自动获得调用接口的权限。</p><div v-if="!menu.length" class="empty compact"><Icon name="layers" :size="30"/><p>尚无可用导航</p></div><div v-for="item in menu" :key="item.id" class="menu-tree-row" :style="{paddingLeft:16+item.depth*22+'px'}"><Icon :name="item.type==='MENU'?'layers':'key'"/><strong>{{item.name}}</strong><span :class="['badge',item.granted?'green':'neutral']">{{item.granted?'已授权':'导航容器'}}</span></div></section><section class="panel api-demo"><div class="section-heading"><h2>接口鉴权验证</h2><span class="badge neutral">示例</span></div><p class="muted">向示例课程接口发起真实请求，验证完整授权链。返回内容为静态示例数据。</p><div class="endpoint"><span class="http-method get">GET</span><code>/api/demo/courses</code></div><button class="primary" :disabled="c.s.busy" @click="result=null;c.run(async()=>{result=await c.api('/api/demo/courses');c.message('接口鉴权通过')})">发送验证请求<Icon name="arrow"/></button><pre v-if="result">{{JSON.stringify(result,null,2)}}</pre><p class="hint"><Icon name="info"/>403 表示缺少有效授权链；管理员身份也不会自动获得业务权限。</p></section></div></template>
